   101	// errGroups folds raw error messages into a deterministic, bounded breakdown:
   102	// normalize each distinct raw once (collapsing this run's volatile URLs/refs),
   103	// tally by the resulting key, then keep the maxDistinctErrors most frequent
   104	// (count desc, message asc) and fold the remainder into "(other errors)".
   105	// Returns nil when there were no errors, so the JSON field is omitted.
   106	func errGroups(raw map[string]int) []ErrGroup {
   107		if len(raw) == 0 {
   108			return nil
   109		}
   110		// Normalize once per distinct raw message, not once per occurrence — an
   111		// outage repeating one error tens of thousands of times normalizes it once.
   112		counts := make(map[string]int, len(raw))
   113		for msg, n := range raw {
   114			counts[normalizeErr(msg)] += n
   115		}
   116		out := make([]ErrGroup, 0, len(counts))
   117		for msg, n := range counts {
   118			out = append(out, ErrGroup{Message: msg, Count: n})
   119		}
   120		byFreq := func(i, j int) bool {
   121			if out[i].Count != out[j].Count {
   122				return out[i].Count > out[j].Count
   123			}
   124			return out[i].Message < out[j].Message
   125		}
   126		sort.Slice(out, byFreq)
   127		if len(out) > maxDistinctErrors {
   128			other := 0
   129			for _, g := range out[maxDistinctErrors:] {
   130				other += g.Count
   131			}
   132			out = append(out[:maxDistinctErrors], ErrGroup{Message: "(other errors)", Count: other})
   133			sort.Slice(out, byFreq) // the overflow bucket may outrank the kept singletons
   134		}
   135		return out
   136	}
