   138	// summarize folds raw samples into a LevelResult, dropping anything inside the
   139	// warm-up window and computing exact percentiles over the OK samples.
   140	func summarize(samples []Sample, concurrency int, strategy string, repos, nodes int,
   141		warmup, window time.Duration, commitFiles string) LevelResult {
   142		r := LevelResult{
   143			Concurrency: concurrency,
   144			Strategy:    strategy,
   145			Repos:       repos,
   146			Nodes:       nodes,
   147			WindowSec:   window.Seconds(),
   148			CommitFiles: commitFiles,
   149		}
   150	
   151		var okDurs, cloneDurs []float64
   152		pushErrs := map[string]int{}
   153		cloneErrs := map[string]int{}
   154		for _, s := range samples {
   155			if s.Offset < warmup {
   156				continue // warm-up: excluded from every statistic
   157			}
   158			if s.Op == OpClone {
   159				r.Clones++
   160				if s.Res == OutcomeOK {
   161					r.CloneOK++
   162					cloneDurs = append(cloneDurs, float64(s.Dur)/float64(time.Millisecond))
   163				} else {
   164					r.CloneErrors++
   165					cloneErrs[s.Msg]++
   166				}
   167				continue
   168			}
   169			r.Pushes++
   170			switch s.Res {
   171			case OutcomeOK:
   172				r.OK++
   173				okDurs = append(okDurs, float64(s.Dur)/float64(time.Millisecond))
   174			case OutcomeCAS:
   175				r.CASFailures++
   176			case OutcomeErr:
   177				r.OtherErrors++
   178				pushErrs[s.Msg]++
   179			}
   180		}
   181		r.ErrorMessages = errGroups(pushErrs)
   182		r.CloneErrorMessages = errGroups(cloneErrs)
   183	
   184		if len(okDurs) > 0 {
   185			sort.Float64s(okDurs)
   186			r.P50ms = percentile(okDurs, 50)
   187			r.P95ms = percentile(okDurs, 95)
   188			r.P99ms = percentile(okDurs, 99)
   189			r.P999ms = percentile(okDurs, 99.9)
   190			r.Maxms = okDurs[len(okDurs)-1]

