    57	    ms: false,
    58	    cursor: { points: { size: 7 } },
    59	    scales: { x: { time: true } },
    60	    axes: baseAxes(unit),
    61	    legend: { live: true },
    62	    series: [
    63	      { value: (u, ts) => (ts == null ? '' : new Date(ts * 1000).toLocaleTimeString()) },
    64	      ...series.map((s) => ({
    65	        label: s.label,
    66	        stroke: s.color,
    67	        width: 2,
    68	        dash: s.dash,
    69	        spanGaps: false,
    70	        points: { show: false },
    71	        value: (u, v) => (v == null ? '–' : unit(v)),
    72	      })),
    73	    ],
    74	    hooks: {
    75	      drawClear: [
    76	        (u) => {
    77	          // Warm-up shading: quieter than data, under the series.
    78	          const { ctx } = u;
    79	          ctx.save();
    80	          ctx.fillStyle = 'rgba(137, 135, 129, 0.07)';
    81	          for (const b of bands()) {
    82	            const x0 = u.valToPos(b.from, 'x', true);
    83	            const x1 = u.valToPos(b.to, 'x', true);
    84	            ctx.fillRect(x0, u.bbox.top, x1 - x0, u.bbox.height);
    85	          }
    86	          ctx.restore();
    87	        },
    88	      ],
    89	    },
    90	  };
    91	
    92	  const u = new uPlot(opts, data, el);
    93	  const ro = new ResizeObserver(() => u.setSize({ width: el.clientWidth, height }));
    94	  ro.observe(el);
    95	
    96	  // setData re-feeds the full arrays (a complete redraw), so pushes coalesce
    97	  // through one requestAnimationFrame: an SSE replay that dispatches thousands
    98	  // of historical buckets costs one redraw per frame, not one per bucket.
    99	  let raf = 0;
   100	  const flush = () => { raf = 0; u.setData(data); };
   101	
   102	  return {
   103	    u,
   104	    push(ts, vals) {
   105	      data[0].push(ts);
   106	      vals.forEach((v, i) => data[i + 1].push(v));
   107	      if (!raf) raf = requestAnimationFrame(flush);
   108	    },
   109	    setAll(rows) {
   110	      // rows: [[ts, v1, v2, …], …]
   111	      if (raf) { cancelAnimationFrame(raf); raf = 0; }
   112	      for (let i = 0; i < data.length; i++) data[i] = rows.map((r) => r[i] ?? null);
   113	      u.setData(data);
   114	    },
   115	    destroy() {
   116	      if (raf) cancelAnimationFrame(raf);
   117	      ro.disconnect();
   118	      u.destroy();
   119	    },
   120	  };
   121	}
