   123	// sweepChart: results vs concurrency (log-2 x), for finished-run comparison.
   124	// seriesData: [{label, color, points: [[concurrency, value], …]}].
   125	export function sweepChart(el, { seriesData, unit = fmtNum, height = 260 }) {
   126	  const xs = [...new Set(seriesData.flatMap((s) => s.points.map((p) => p[0])))].sort((a, b) => a - b);
   127	  const data = [xs, ...seriesData.map((s) => {
   128	    const byX = new Map(s.points);
   129	    return xs.map((x) => byX.has(x) ? byX.get(x) : null);
   130	  })];
   131	
   132	  const opts = {
   133	    width: el.clientWidth || 800,
   134	    height,
   135	    cursor: { points: { size: 8 } },
   136	    scales: { x: { time: false, distr: 3, log: 2 } },
   137	    axes: [
   138	      { ...baseAxes(unit)[0], values: (u, splits) => splits.map((v) => (v == null ? '' : String(v))) },
   139	      baseAxes(unit)[1],
   140	    ],
   141	    legend: { live: true },
   142	    series: [
   143	      { label: 'concurrency' },
   144	      ...seriesData.map((s) => ({
   145	        label: s.label,
   146	        stroke: s.color,
   147	        width: 2,
   148	        spanGaps: true,
   149	        points: { show: true, size: 7, fill: s.color },
   150	        value: (u, v) => (v == null ? '–' : unit(v)),
   151	      })),
   152	    ],
   153	  };
   154	
   155	  const u = new uPlot(opts, data, el);
   156	  const ro = new ResizeObserver(() => u.setSize({ width: el.clientWidth, height }));
   157	  ro.observe(el);
   158	  return { u, destroy() { ro.disconnect(); u.destroy(); } };
   159	}
